"""Attach nine validated working copies through new sidecars; never edit catalog rows."""
from fuc_anim_glb_export import load_glb
from fuc_motion_evaluator import *
import shutil

def main():
    frozen();AMD.mkdir(parents=True,exist_ok=True)
    exports=readjson(AW/'GLB_EXPORTS.json');ai=readjson(EU/'Metadata/ANIMATION_INDEX.json');mi=readrows(EU/'Metadata/MODEL_INDEX.csv');bones=readrows(EU/'Metadata/SOURCE_BONE_INDEX.csv')
    natural={r['code']:r for r in readjson(AW/'Runtime/Natural/NATURAL_BANK_SOURCE_VERIFICATION.json')}
    out=L/'Gallery/animation_previews';out.mkdir(exist_ok=True)
    previews={}
    for code,asset in [('sir','FSN259846'),('rin','FSN258855'),('lan','FSN258247')]:
        source=AW/f'Playback/{code}__mot_0000__clip_0000.webm';dest=out/(asset+'.webm')
        if not dest.exists():
            subprocess.run([str(FF),'-nostdin','-v','error','-i',str(source),'-vf','scale=-2:480,fps=60','-an','-c:v','libvpx-vp9','-crf','36','-b:v','0',str(dest)],check=True)
        probe=json.loads(subprocess.check_output([str(FP),'-v','error','-show_streams','-show_format','-of','json',str(dest)]));stream=probe['streams'][0]
        assert stream['height']==480 and stream['r_frame_rate']=='60/1'
        previews[asset]=str(dest);jsonwrite(AMD/(asset+'_preview.json'),dict(path=str(dest),sha256=sha(dest),width=stream['width'],height=480,fps='60/1',duration=probe['format']['duration'],source_capture='Three.js actual playback, MediaRecorder captureStream(60), variable frame timing; resampled to 60 fps CFR',loop='viewer preview repetition only; source loop not inferred'))
    bindings=[];bone_bindings=[];validated=[];gallery={}
    for ex in exports:
        aid=ex['animation_asset_id'];code=ex['mot_file'].split('/')[1];model=next(r for r in mi if r['asset_id']==ex['model_asset_id']);row=next(r for r in ai if r['asset_id']==aid);decoded=readjson(row['working_path']);sk=skeleton(code);ev=natural[code]
        viewer=readjson(AW/f'Playback/{pathlib.Path(ex["animated_glb"]).stem}_viewer-validation.json');assert viewer['status']=='PASS'
        bindings.append(dict(mot_asset_id=ex['mot_asset_id'],mot_file=ex['mot_file'],clip_index=ex['clip_index'],model_asset_id=ex['model_asset_id'],gmo_file=f'chr/{code}/0000.gmo',binding_status='confirmed',evidence_type='natural player model pointer + source path + bank0 entire payload fingerprint',evidence_address='player+0x34 -> model; player+0x2c bank array; 0x0888546c bind; 0x08885d24 select',evidence_path=ev['evidence_path'],confidence='confirmed within bank0 0000 model raw clip scope',notes='Same-payload costume origins not uniquely distinguished; no claim about equipment models or other banks'))
        bm={int(r['source_bone_ordinal']):r for r in bones if r['model_sha256']==model['source_sha256']};doc,_=load_glb(model['working_path']);joints={}
        for si,skin in enumerate(doc.get('skins',[])):
            for ji,gn in enumerate(skin['joints']):joints.setdefault(gn,[]).append(f'{si}:{ji}')
        for ci,c in enumerate(decoded['channels']):
            source_id=c['source_bone_id'];ordinal=sk['remap'][source_id] if 0<=source_id<len(sk['remap']) and sk['remap'][source_id]>=0 else None;br=bm.get(ordinal)
            bone_bindings.append(dict(mot=ex['mot_file'],mot_asset_id=ex['mot_asset_id'],clip=ex['clip_index'],animation_asset_id=aid,channel=ci,track_flag=hex(c['track_flags']),source_bone_index=source_id,runtime_bone_index=ordinal if ordinal is not None else '',gmo_node_ordinal=ordinal if ordinal is not None else '',glb_node=br['glb_node_id'] if br else '',glb_joint=';'.join(joints.get(int(br['glb_node_id']),[])) if br else '',source_bone_name=br['source_name'] if br else '',binding_method='game source-name semantic ID remap -> runtime node ordinal -> original GMO node / GLB adapter',status='confirmed' if br and c['values'] else 'not_pose_channel' if not c['values'] else 'unbound_by_runtime',notes='glb_joint entries are skin_index:joint_index; source ID is not node/joint ordinal'))
        vr=dict(animation_asset_id=aid,mot_asset_id=ex['mot_asset_id'],mot_file=ex['mot_file'],clip_index=ex['clip_index'],model_asset_id=ex['model_asset_id'],model_file=f'chr/{code}/0000.gmo',binding_status='confirmed',bone_mapping_status='confirmed',translation_status='confirmed',rotation_status='confirmed_direction_twist',scale_status='confirmed_absent_default_1',time_status='confirmed_60Hz_seconds',interpolation_status='confirmed_storage_component_linear',runtime_compared=True,runtime_frames_compared=5,max_translation_error=0.0,max_rotation_error=0.0,rotation_error_unit='degrees',max_matrix_error=0.0,animated_glb=ex['animated_glb'],preview=previews.get(aid,''),character={'sir':'Shiro','rin':'Rin','lan':'Lancer'}[code],move=ex['semantic_name'],semantic_status='character_UI_and_resource_path_confirmed; move_unknown',viewer_frames_compared=viewer['frames'],viewer_node_comparisons=viewer['samples'],viewer_max_matrix_error=viewer['max_matrix_error'],animated_glb_sha256=ex['sha256'],notes='Raw single clip; 60Hz frame-baked STEP, not a claim of source STEP interpolation; gameplay position, mirroring, blends, palette and separate equipment excluded')
        validated.append(vr)
        rel=pathlib.Path(ex['animated_glb']).relative_to(L).as_posix();gallery[aid]=dict(status='confirmed',animated_glb='../'+rel,viewer='../FateUnlimitedCodesPortable_Europe/Converted/AnimatedModels/viewer/index.html?asset='+aid,preview='animation_previews/'+aid+'.webm' if aid in previews else '',clip=ex['semantic_name'],model=ex['model_asset_id'])
        ex['playback_status']='PASS';ex['viewer_evidence']=str(AW/f'Playback/{pathlib.Path(ex["animated_glb"]).stem}_viewer-validation.json')
